import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>تحويل صيغة صورة يبدو تقنيًا، لكن العمل كله يستغرق أقل من دقيقة. ست خطوات سريعة تفصلك عن ملف بالصيغة التي تحتاجها.</p>\n<p>لا برنامج لتثبيته، ولا حساب لإنشائه، ولا انتظار لرفع إلى خادم. كل شيء يعمل في متصفحك على جهازك.</p>\n<p>يمر هذا الدليل بكل خطوة بالترتيب، مع الإعدادات التي تهم والأخطاء التي يجب تجنبها.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: ما الذي تحتاجه؟</h2>\n<p>قبل أن تبدأ، تحتاج إلى الصورة الأصلية ومعرفة الصيغة المطلوبة. تحقق من متطلبات الوجهة: أي صيغة تقبل، وأي حجم تفضل.</p>\n<p>إذا كانت صورتك بصيغة غير معتادة مثل HEIC أو BMP، فلا مشكلة. المحول يدعم معظم الصيغ الشائعة.</p>\n<h2 id=\"step-1-upload\">الخطوة 1: ارفع صورتك</h2>\n<p>افتح <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> في متصفحك وارفع صورتك. أسقط الملف في منطقة الرفع أو اختره من جهازك.</p>\n<p>تُقبل ملفات JPG وPNG وWebP وHEIC وBMP وGIF وAVIF، بحجم إدخال يصل إلى 25 ميغابايت.</p>\n<h2 id=\"step-2-pick-output-format\">الخطوة 2: اختر صيغة الإخراج</h2>\n<p>اختر صيغة الإخراج حسب وجهتك: JPG للتوافق الكامل، وPNG للنصوص والشفافية، وWebP لأصغر حجم على المواقع الحديثة.</p>\n<p>إذا لم تكن متأكدًا، فاختر JPG. يعمل في كل مكان تقريبًا، وهو الخيار الآمن عندما لا تعرف متطلبات الوجهة.</p>\n<h2 id=\"step-3-set-quality\">الخطوة 3: اضبط منزلق الجودة</h2>\n<p>اضبط منزلق الجودة: 80 إلى 90 مناسب لمعظم الاستخدامات، و95 للجودة القصوى. الجودة الأعلى تعني ملفًا أكبر.</p>\n<p>للتحويل إلى PNG، لا يؤثر منزلق الجودة لأن PNG دون فقدان. أما JPG وWebP فيستخدمان الجودة لتحديد مقدار الضغط.</p>\n<h2 id=\"step-4-transparency-fill\">الخطوة 4: تعامل مع الشفافية (JPG فقط)</h2>\n<p>تعامل مع الشفافية عند التحويل إلى JPG فقط. JPG لا يدعم الشفافية، لذلك يجب ملء المناطق الشفافة بلون.</p>\n<p>اختر لون تعبئة يناسب خلفية موقعك أو مستندك. الأبيض هو الخيار الافتراضي، لكن لون موقعك قد يكون أفضل.</p>\n<h2 id=\"step-5-convert-and-preview\">الخطوة 5: حوّل وعاين النتيجة</h2>\n<p>حوّل وعاين النتيجة: قارن الصورة المحوّلة بالأصل، وكبّرها وافحص التفاصيل المهمة. تأكد من أن الألوان صحيحة والنص واضح.</p>\n<p>إذا بدت النتيجة جيدة، فهي جاهزة. وإذا بدت أسوأ، فأعد التحويل بجودة أعلى أو صيغة مختلفة.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل صورتك المحوّلة</h2>\n<p>نزّل صورتك المحوّلة واحفظها باسم واضح. الأداة تضيف لاحقة توضح الصيغة الجديدة، مثل sora.png.</p>\n<p>تحقق من الملف المنزّل قبل استخدامه: افتحه وتأكد من أنه يعمل ويبدو صحيحًا.</p>\n<ol>\n<li>ارفع صورتك إلى المحول.</li>\n<li>اختر صيغة الإخراج والجودة.</li>\n<li>حوّل وعاين النتيجة.</li>\n<li>نزّل الملف المحوّل.</li>\n</ol>\n<h2 id=\"converting-on-your-phone\">كيف تحوّل الصور على هاتفك؟</h2>\n<p>تحويل الصور على هاتفك سهل: افتح المحول في المتصفح وارفع الصورة من معرضك. التحويل يحدث على جهازك دون تطبيق إضافي.</p>\n<p>على الشاشات الصغيرة، تأكد من اختيار الصيغة الصحيحة قبل التحويل. الخطأ في الصيغة على الهاتف سهل الحدوث.</p>\n<h2 id=\"converting-many-files-at-once\">كيف تحوّل صورًا كثيرة دفعة واحدة؟</h2>\n<p>لتحويل صور كثيرة دفعة واحدة، استخدم محول الصور بالجملة. ارفع كل الصور واختر الصيغة نفسها للجميع.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا بدت العينة جيدة، فغالبًا بقية الصور بنفس الجودة.</p>\n<h2 id=\"fixing-common-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. النتيجة الباهتة تعني جودة منخفضة، والنتيجة الكبيرة تعني صيغة غير مناسبة.</p>\n<p>أعد التحويل من الملف الأصلي بإعدادات مختلفة. لا تعيد التحويل من النسخة المحوّلة، لأن كل جولة تضيف ضررًا.</p>\n<h2 id=\"checking-the-result\">كيف تراجع النتيجة قبل إرسالها؟</h2>\n<p>راجع النتيجة قبل إرسالها: افتح الملف المنزّل وتأكد من أنه يعمل ويبدو صحيحًا وأن حجمه مناسب.</p>\n<p>تحقق أيضًا من الصيغة: تأكد من أن الملف بالصيغة المطلوبة فعلًا، لا بصيغة الأصل. الخطأ في الصيغة شائع بعد التحويل.</p>\n<h2 id=\"when-to-use-a-dedicated-converter\">متى تستخدم محولًا مخصصًا؟</h2>\n<p>استخدم محولًا مخصصًا عندما تحتاج إلى صيغة خاصة: HEIC إلى JPG، أو SVG إلى PNG، أو تحويل جماعي بصيغة موحدة.</p>\n<p>لتحويل HEIC إلى JPG، استخدم <a href=\"/ar/tahwil-heic-ila-jpg/\">محول HEIC إلى JPG</a>. ولتحويل SVG إلى PNG، استخدم <a href=\"/ar/tahwil-svg-ila-png/\">محول SVG إلى PNG</a>. وللدفعات، استخدم <a href=\"/ar/tahwil-jumli-lis-suwar/\">محول الصور بالجملة</a>.</p>\n<h2 id=\"single-vs-batch\">كيف تختار بين التحويل الفردي والجماعي؟</h2>\n<p>للاختيار بين التحويل الفردي والجماعي: فردي عندما تحتاج إعدادات مختلفة لكل صورة، وجماعي عندما تحتاج الصيغة نفسها للجميع.</p>\n<p>الدفعات توفر الوقت، لكن التحويل الفردي يعطي تحكمًا أفضل. اختر حسب عدد الصور وتشابه احتياجاتها.</p>\n<h2 id=\"converting-from-email\">كيف تحوّل صور مرفقات البريد؟</h2>\n<p>لتحويل صور من مرفقات البريد، نزّل المرفق أولًا ثم ارفعه إلى المحول. لا تحوّل الصورة مباشرة من البريد دون تنزيل.</p>\n<p>إذا كان المرفق كبيرًا، فانتظر حتى يكتمل التنزيل قبل الرفع. الملف غير المكتمل يفشل في التحويل.</p>\n<h2 id=\"converting-for-social-media\">كيف تحوّل الصور لوسائل التواصل؟</h2>\n<p>لتحويل الصور لوسائل التواصل، اختر الصيغة والأبعاد المناسبة لكل منصة. إنستغرام يفضل مربعًا، وفيسبوك يفضل 1200 في 630 بكسل.</p>\n<p>حوّل إلى JPG لضمان التوافق. معظم المنصات تقبل JPG دون مشاكل، بينما WebP قد يُرفض في بعضها.</p>\n<h2 id=\"when-the-result-looks-wrong\">ماذا تفعل عندما تبدو النتيجة خاطئة؟</h2>\n<p>عندما تبدو النتيجة خاطئة، فافحص ثلاثة أشياء: الجودة، والصيغة، ولون التعبئة. أحدها غالبًا هو السبب.</p>\n<p>أعد التحويل من الملف الأصلي بإعدادات مصححة. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-as-suwar/\">الدليل الكامل لمحول الصور</a> و<a href=\"/ar/blog/faqd-al-jawda-fi-tahwil-sighat-as-suwar/\">تحويل صيغة الصورة: فقدان الجودة</a>. وإذا أردت مستندًا، فجرّب <a href=\"/ar/tahwil-as-suwar-ila-pdf/\">محول الصور إلى PDF</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم يستغرق تحويل صيغة صورة؟","answer":"أقل من دقيقة لصورة واحدة. الرفع والتحويل والتنزيل كلها سريعة، والصور الكبيرة جدًا قد تأخذ وقتًا أطول قليلًا."},{"question":"هل يمكنني تحويل صيغة صورة على هاتفي دون تطبيق؟","answer":"نعم، افتح المحول في متصفح هاتفك وارفع الصورة من معرضك. التحويل يحدث على جهازك دون الحاجة إلى تطبيق إضافي."},{"question":"إلى أي صيغة أحوّل صورتي لطلب توظيف؟","answer":"JPG هو الخيار الآمن لطلبات التوظيف. تقبله كل البوابات، ويعطي ملفات صغيرة بجودة جيدة. تجنب WebP وHEIC في البوابات."},{"question":"هل يمكنني تحويل لقطة شاشة إلى صيغة أصغر؟","answer":"نعم، حوّل لقطة PNG إلى JPG لتقليل حجمها بشكل كبير. النص قد يفقد بعض حدته، لذلك حافظ على الأبعاد كبيرة وراجع النص بعد التحويل."},{"question":"لماذا ملف WebP المحوّل أكبر من ملف JPG الأصلي؟","answer":"لأن WebP يحفظ بعض البيانات بشكل مختلف، وقد تكون صورتك الأصلية مضغوطة بكفاءة أصلًا. إذا كان WebP أكبر، فاحتفظ بـJPG."},{"question":"هل يمكنني تحويل الصورة نفسها إلى صيغتين دون إعادة رفعها؟","answer":"نعم، يمكنك تحويل الصورة نفسها إلى صيغتين دون إعادة رفعها. غيّر صيغة الإخراج بعد التحويل الأول وشغّل التحويل مجددًا من الملف المرفوع نفسه."}];
